"""Parser for rgblink .sym files (e.g. pret/pokeyellow's pokeyellow.sym).

Format, one symbol per line::

    ; File generated by rgblink
    00:d35d wCurMap
    00:d360 wYCoord

The bank is irrelevant for WRAM0 addresses we read, but kept for completeness.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class Symbol:
    bank: int
    address: int
    name: str


class SymbolTable:
    def __init__(self, symbols: dict[str, Symbol]):
        self._symbols = symbols

    @classmethod
    def parse(cls, text: str) -> SymbolTable:
        symbols: dict[str, Symbol] = {}
        for raw in text.splitlines():
            line = raw.split(";", 1)[0].strip()
            if not line:
                continue
            try:
                location, name = line.split(maxsplit=1)
                bank_s, addr_s = location.split(":")
                symbols[name] = Symbol(int(bank_s, 16), int(addr_s, 16), name)
            except ValueError:
                continue  # tolerate odd lines instead of failing the whole file
        return cls(symbols)

    @classmethod
    def load(cls, path: str | Path) -> SymbolTable:
        return cls.parse(Path(path).read_text(encoding="utf-8"))

    def addr(self, name: str) -> int:
        try:
            return self._symbols[name].address
        except KeyError as exc:
            raise KeyError(f"symbol not found: {name!r} (wrong .sym file?)") from exc

    def bank(self, name: str) -> int:
        try:
            return self._symbols[name].bank
        except KeyError as exc:
            raise KeyError(f"symbol not found: {name!r} (wrong .sym file?)") from exc

    def __contains__(self, name: str) -> bool:
        return name in self._symbols

    def __len__(self) -> int:
        return len(self._symbols)
